import json,glob
from pathlib import Path
root=Path(__file__).resolve().parents[2]
seeds={s['id']:s for p in (root/'taxonomy/seeds').glob('*.json') for s in json.load(open(p))}
activities=[x for x in json.load(open(root/'taxonomy/company_rules/observed_activities.json')) if 40<=int(x['okved'].split('.')[0])<=69]
D='declared_activity'; C='activity_scope_candidate'; E='operating_exposure'
def m(s,inds,rel,why,sigs=None):
 sid={'s':'services','i':'industry','c':'crosscut'}[s[0]]+'_'+s[1:].zfill(2); sec=seeds[sid]
 if inds=='*': inds=range(10)
 return dict(sector_id=sid,objects=[sec['objects'][i]['name'] for i in inds],relation=rel,reason=why,signal_names=[] if sigs is None else [sec['signals'][i]['name'] for i in sigs])
def exposure(s,inds,why):return m(s,inds,E,why,[0,1,8,9] if s.startswith('i') else None)
