rows=[]
for a in activities:
 code=a['okved'];keys=[k for k in spec if code==k or code.startswith(k+'.')]
 if not keys: raise Exception('NO RULE '+str(a))
 key=max(keys,key=len);maps=spec[key]
 gap=gaps.get(code)
 if code.startswith('68.1') or code.startswith('68.31') or code=='68.3':gap='В исходном словаре нет объектов покупки/продажи недвижимости и риелторского посредничества; сохранены только косвенные юридические темы.'
 if code=='68.20.1':gap='В исходном словаре нет аренды жилой недвижимости; коммерческая аренда не присвоена.'
 if code in ['43.11','43.12','43.12.3','43.13']:gap='Прямой вид строительных работ отсутствует в словаре; сохранены только связанные материалы/техника.'
 if not gap and not any(mm['relation'] in (D,C) for mm in maps):
  gap='Основная деятельность «'+a['activity']+'» не имеет достаточно точного прямого объекта в исходном справочнике либо код не раскрывает конкретный товар/услугу; назначены только косвенные операционные интересы.'
 rows.append(dict(okved=code,activity=a['activity'],mappings=maps,unmapped_reason=gap))
for row in rows:
 seen=set()
 for x in row['mappings']:
  s=seeds[x['sector_id']]
  assert all(v in [o['name'] for o in s['objects']] for v in x['objects'])
  assert all(v in [o['name'] for o in s['signals']] for v in x['signal_names'])
  key=(x['sector_id'],tuple(x['objects']),x['relation']);assert key not in seen;seen.add(key)
assert len(set(r['okved'] for r in rows))==len(rows)==291
out=root/'taxonomy/okved_mapping/trade.json';out.write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
print('codes',len(rows),'mappings',sum(len(r['mappings']) for r in rows),'objects',sum(len(m['objects']) for r in rows for m in r['mappings']),'gaps',sum(bool(r['unmapped_reason']) for r in rows))
